#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const int MOD_CONST=1000000007;
typedef long long LL;
LL number_input;
int digit_count, base_number, total_result, position_index, digits_array[110];

void add_mod(int &x, int y, int m) {
    x += y; if (x >= m) x -= m;
}

struct Matrix {
    int mat[35][35];
    Matrix() { memset(mat, 0, sizeof(mat)); }
    Matrix operator*(const Matrix &other) const {
        Matrix res;
        for (int k=0; k<=base_number; k++)
            for (int i=0; i<=base_number; i++)
                if (mat[i][k])
                    for (int j=0; j<=base_number; j++)
                        if (other.mat[k][j])
                            res.mat[i][j] = (1LL * mat[i][k] * other.mat[k][j] + res.mat[i][j]) % MOD_CONST;
        return res;
    }
} answerMatrix, sMatArr[75][35], prefixMatArr[75][35], suffixMatArr[75][35];

void parseNumber(LL number) {
    LL temp=number;
    digit_count=0;
    while (temp) {
        digits_array[++digit_count]=temp%base_number;
        temp/=base_number;
    }
    reverse(digits_array+1, digits_array+digit_count+1);
}

int main() {
    scanf("%lld%d", &number_input, &base_number);
    parseNumber(number_input);
    for (int i=0; i<base_number; i++) {
        for (int j=0; j<=base_number; j++) sMatArr[0][i].mat[j][j]=1;
        for (int j=0; j<=base_number; j++) sMatArr[0][i].mat[i][j]=1;
    }
    for (int i=1; i<=digit_count; i++) {
        prefixMatArr[i-1][0]=sMatArr[i-1][0];
        suffixMatArr[i-1][base_number-1]=sMatArr[i-1][base_number-1];
        for (int j=1; j<base_number; j++) prefixMatArr[i-1][j]=prefixMatArr[i-1][j-1]*sMatArr[i-1][j];
        for (int j=base_number-2; j>=0; j--) suffixMatArr[i-1][j]=sMatArr[i-1][j]*suffixMatArr[i-1][j+1];
        for (int j=0; j<base_number; j++)
            if (j) sMatArr[i][j]=suffixMatArr[i-1][j]*prefixMatArr[i-1][j-1];
            else sMatArr[i][j]=suffixMatArr[i-1][j];
    }
    for (int i=0; i<=base_number; i++)
        for (int j=0; j<=base_number; j++)
            answerMatrix.mat[i][j]=(i==j);
    position_index=0;
    for (int i=1; i<=digit_count; i++) {
        if (digits_array[i]) {
            if (position_index+digits_array[i]-1>=base_number) {
                for (int j=position_index; j<base_number; j++) answerMatrix=answerMatrix*sMatArr[digit_count - i][j];
                for (int j=0; j<=(position_index+digits_array[i]-1)-base_number; j++) answerMatrix=answerMatrix*sMatArr[digit_count - i][j];
            } else {
                for (int j=position_index; j<=position_index+digits_array[i]-1; j++) answerMatrix=answerMatrix*sMatArr[digit_count - i][j];
            }
            add_mod(position_index, digits_array[i], base_number);
        }
    }
    for (int i=0; i<=base_number; i++) add_mod(total_result, answerMatrix.mat[i][base_number], MOD_CONST);
    printf("%d\n", total_result);
    return 0;
}
